organization_id = 2

def get_cell_color(actual_das, ideal_das_from, ideal_das_to):
    if ideal_das_from <= actual_das <= ideal_das_to:
        return 'green'
    elif actual_das:
        return 'yellow'
    else:
        return 'red'

def dashboard_view(request):
    # Filter farms and activities based on organization ID
    
    farms = farm.objects.filter(org_id=organization_id)
    activities = ActivityRecord.objects.filter(organization=organization_id)
    
    # Get all DASActivityRecords for the farms in a single query
    das_activity_records = DASActivityRecord.objects.filter(farm__in=farms).select_related('activity')
    
    # Get all ActivityPOP records for the activities in a single query
    activity_pops = ActivityPOP.objects.filter(activity_records_id__in=activities).select_related('activity_records_id')
    
    # Create a lookup dictionary for ActivityPOP by activity
    activity_pop_lookup = {activity_pop.activity_records_id_id: activity_pop for activity_pop in activity_pops}
    
    # Create a lookup dictionary for DASActivityRecord by farm and activity
    das_activity_lookup = {}
    for das_activity in das_activity_records:
        farm_id = das_activity.farm_id
        activity_id = das_activity.activity_id
        if farm_id not in das_activity_lookup:
            das_activity_lookup[farm_id] = {}
        das_activity_lookup[farm_id][activity_id] = das_activity
    
    # Prepare the data for the table
    table_data = []
    for farm_instance in farms:
        farm_row = []
        for activity in activities:
            farm_id = farm_instance.id
            activity_id = activity.id
            if farm_id in das_activity_lookup and activity_id in das_activity_lookup[farm_id]:
                das_activity = das_activity_lookup[farm_id][activity_id]
                activity_pop = activity_pop_lookup.get(activity_id)
                if activity_pop:
                    actual_das = das_activity.day_of_sowing
                    ideal_das_from = activity_pop.from_das
                    ideal_das_to = activity_pop.to_das
                    if ideal_das_to:
                        cell_color = get_cell_color(actual_das, ideal_das_from, ideal_das_to)
                else:
                    cell_color = 'red'
            else:
                cell_color = 'red'
            farm_row.append({'activity': activity.name, 'color': cell_color})
        table_data.append({'farm': farm_instance.name, 'activities': farm_row})

    # Render the template with the table data
    return render(request, 'dashboard/dashboard.html', {'table_data': table_data, 'activities': activities})




def get_cell_color_csv(activity, actual_das, ideal_das_from, ideal_das_to):
    if actual_das >= ideal_das_from and actual_das <= ideal_das_to:
        return 'green'
    elif activity:
        return 'yellow'
    else:
        return 'red'

def dashboard_view_csv(request):
    # Load the CSV data
    data = csv_data

    # Extract unique farms and activities
    farms = list(set(row['FarmName'] for row in data))
    activities = ["Field Preparation", "Fertilizer application", "sowing", "irrigation", "pest control", "weed management"]

    # Prepare the data for the table
    table_data = []
    for farm in farms:
        farm_row = []
        farm_data = [row for row in data if row['FarmName'] == farm]
        for activity in activities:
            activity_data = [row for row in farm_data if row['Activity'] == activity]
            if activity_data:
                actual_das = int(activity_data[0]['Activity DAS'])
                ideal_das_from = int(activity_data[0]['Ideal DAS from'])
                ideal_das_to = int(activity_data[0]['Ideal DAS to'])
                cell_color = get_cell_color_csv(activity, actual_das, ideal_das_from, ideal_das_to)
            else:
                cell_color = 'red'
            farm_row.append({'activity': activity, 'color': cell_color})
        table_data.append({'farm': farm, 'activities': farm_row})

    # Render the template with the table data
    return render(request, 'dashboard/dashboard_with_csv.html', {'table_data': table_data, 'activities': activities})


def dashboard_farm_for_activity(request):
    data= Setting.objects.filter(key="DASHBOARD_ORG").all()
    if data:
        for i in data:
            organization_id=i.value
    farms_data=farm.objects.filter(org_id=organization_id).all()[:400]
    farm_id=None
    if farms_data:
        farm_id=farms_data[0].id
    if request.GET.get('farm_id'):
        farm_id=request.GET.get('farm_id')
    activities=DASActivityRecord.objects.filter(farm_id=farm_id).prefetch_related('das_activity_record_img').order_by('-id').all()[:2]
    if activities:
        activities=DASActivityRecordSerializer(activities,many=True)
        if activities:
            activities=activities.data
    
    return render(request, 'dashboard/dashboard_farm_for_activity.html', {'farm_data': farms_data, 'farm_id': farm_id, 'activities':activities})


